# Create AIChat component - chat interface for HF Spaces API
aichat_tsx = '''import React, { useState, useRef, useEffect } from 'react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { hfApi } from '@/lib/hf-api'
import { cn } from '@/lib/utils'

interface Message {
  id: string
  text: string
  sender: 'user' | 'ai'
  timestamp: Date
  type?: 'text' | 'image' | 'audio'
}

interface AIModel {
  id: string
  name: string
  description: string
  type: 'text' | 'image' | 'audio'
}

const availableModels: AIModel[] = [
  { id: 'text-generation', name: 'Text Generation', description: 'Generate creative text content', type: 'text' },
  { id: 'sentiment-analysis', name: 'Sentiment Analysis', description: 'Analyze text sentiment', type: 'text' },
  { id: 'summarization', name: 'Text Summarization', description: 'Summarize long texts', type: 'text' },
  { id: 'image-classification', name: 'Image Classification', description: 'Classify images', type: 'image' },
]

export function AIChat() {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: '1',
      text: 'Hello! I\'m your OASIS AI assistant. How can I help you today?',
      sender: 'ai',
      timestamp: new Date(),
      type: 'text'
    }
  ])
  const [inputText, setInputText] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [selectedModel, setSelectedModel] = useState<string>('text-generation')
  const [error, setError] = useState<string | null>(null)
  const messagesEndRef = useRef<HTMLDivElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }

  useEffect(() => {
    scrollToBottom()
  }, [messages])

  const handleSendMessage = async () => {
    if (!inputText.trim() || isLoading) return

    const userMessage: Message = {
      id: Date.now().toString(),
      text: inputText,
      sender: 'user',
      timestamp: new Date(),
      type: 'text'
    }

    setMessages(prev => [...prev, userMessage])
    setInputText('')
    setIsLoading(true)
    setError(null)

    try {
      // Call HF Spaces API based on selected model
      let response
      switch (selectedModel) {
        case 'text-generation':
          response = await hfApi.generateText(inputText)
          break
        case 'sentiment-analysis':
          response = await hfApi.analyzeSentiment(inputText)
          break
        case 'summarization':
          response = await hfApi.summarizeText(inputText)
          break
        default:
          response = await hfApi.generateText(inputText)
      }

      const aiMessage: Message = {
        id: (Date.now() + 1).toString(),
        text: response.result || response.generated_text || 'No response generated',
        sender: 'ai',
        timestamp: new Date(),
        type: 'text'
      }

      setMessages(prev => [...prev, aiMessage])
    } catch (error) {
      console.error('Error calling AI API:', error)
      setError('Sorry, I encountered an error. Please try again.')

      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        text: 'Sorry, I encountered an error processing your request. Please try again.',
        sender: 'ai',
        timestamp: new Date(),
        type: 'text'
      }

      setMessages(prev => [...prev, errorMessage])
    } finally {
      setIsLoading(false)
      inputRef.current?.focus()
    }
  }

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSendMessage()
    }
  }

  const clearChat = () => {
    setMessages([{
      id: '1',
      text: 'Hello! I\'m your OASIS AI assistant. How can I help you today?',
      sender: 'ai',
      timestamp: new Date(),
      type: 'text'
    }])
    setError(null)
  }

  return (
    <div className="flex flex-col h-screen max-h-screen">
      {/* Header */}
      <Card className="border-b rounded-none">
        <CardHeader className="pb-3">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <div>
              <CardTitle className="text-lg">OASIS AI Chat</CardTitle>
              <p className="text-sm text-muted-foreground">
                Powered by Hugging Face Spaces
              </p>
            </div>
            <div className="flex flex-wrap gap-2">
              <select 
                value={selectedModel}
                onChange={(e) => setSelectedModel(e.target.value)}
                className="text-xs px-3 py-1 border rounded-md bg-background"
                aria-label="Select AI model"
              >
                {availableModels.map(model => (
                  <option key={model.id} value={model.id}>
                    {model.name}
                  </option>
                ))}
              </select>
              <Button 
                variant="outline" 
                size="sm" 
                onClick={clearChat}
                className="text-xs"
              >
                Clear Chat
              </Button>
            </div>
          </div>
        </CardHeader>
      </Card>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((message) => (
          <div
            key={message.id}
            className={cn(
              "flex",
              message.sender === 'user' ? 'justify-end' : 'justify-start'
            )}
          >
            <div
              className={cn(
                "max-w-[80%] sm:max-w-[70%] rounded-lg p-3 text-sm",
                message.sender === 'user'
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-muted text-muted-foreground border'
              )}
            >
              <p className="whitespace-pre-wrap break-words">{message.text}</p>
              <p className="text-xs opacity-70 mt-1">
                {message.timestamp.toLocaleTimeString()}
              </p>
            </div>
          </div>
        ))}

        {isLoading && (
          <div className="flex justify-start">
            <div className="bg-muted text-muted-foreground rounded-lg p-3 border">
              <div className="flex items-center space-x-2">
                <div className="flex space-x-1">
                  <div className="w-2 h-2 bg-current rounded-full animate-bounce" style={{animationDelay: '0ms'}}></div>
                  <div className="w-2 h-2 bg-current rounded-full animate-bounce" style={{animationDelay: '150ms'}}></div>
                  <div className="w-2 h-2 bg-current rounded-full animate-bounce" style={{animationDelay: '300ms'}}></div>
                </div>
                <span className="text-xs">AI is thinking...</span>
              </div>
            </div>
          </div>
        )}

        {error && (
          <div className="flex justify-center">
            <Badge variant="destructive" className="text-xs">
              {error}
            </Badge>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input */}
      <Card className="border-t rounded-none">
        <CardContent className="p-4">
          <div className="flex space-x-2">
            <Input
              ref={inputRef}
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              onKeyPress={handleKeyPress}
              placeholder={`Ask ${availableModels.find(m => m.id === selectedModel)?.name || 'AI'}...`}
              disabled={isLoading}
              className="flex-1"
              aria-label="Chat message input"
            />
            <Button 
              onClick={handleSendMessage}
              disabled={!inputText.trim() || isLoading}
              size="icon"
              aria-label="Send message"
            >
              <svg 
                className="h-4 w-4" 
                fill="none" 
                stroke="currentColor" 
                viewBox="0 0 24 24"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path 
                  strokeLinecap="round" 
                  strokeLinejoin="round" 
                  strokeWidth={2} 
                  d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" 
                />
              </svg>
            </Button>
          </div>
          <p className="text-xs text-muted-foreground mt-2">
            Model: {availableModels.find(m => m.id === selectedModel)?.description}
          </p>
        </CardContent>
      </Card>
    </div>
  )
}
'''

with open("/home/user/output/src/components/AIChat.tsx", "w") as f:
    f.write(aichat_tsx)

print("✅ Created AIChat component")

# Create SubscriptionManager component - Stripe subscription management
subscription_tsx = '''import React, { useState, useEffect } from 'react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Progress } from '@/components/ui/progress'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { stripeService } from '@/lib/stripe'
import { supabase } from '@/lib/supabase'

interface SubscriptionTier {
  id: string
  name: string
  price: number
  interval: 'month' | 'year'
  features: string[]
  apiCalls: number
  stripePriceId: string
  popular?: boolean
}

interface UserSubscription {
  id: string
  tier: string
  status: 'active' | 'cancelled' | 'past_due' | 'unpaid'
  currentPeriodEnd: Date
  apiCallsUsed: number
  apiCallsLimit: number
}

const subscriptionTiers: SubscriptionTier[] = [
  {
    id: 'free',
    name: 'Free',
    price: 0,
    interval: 'month',
    features: [
      '1,000 API calls/month',
      'Basic AI models',
      'Community support',
      'Mobile client access'
    ],
    apiCalls: 1000,
    stripePriceId: '',
  },
  {
    id: 'pro',
    name: 'Pro',
    price: 29,
    interval: 'month',
    features: [
      '50,000 API calls/month',
      'All AI models',
      'Priority processing',
      'Email support',
      'Analytics dashboard',
      'Custom integrations'
    ],
    apiCalls: 50000,
    stripePriceId: 'price_pro_monthly',
    popular: true,
  },
  {
    id: 'enterprise',
    name: 'Enterprise',
    price: 99,
    interval: 'month',
    features: [
      'Unlimited API calls',
      'Dedicated support',
      'Custom models',
      'SLA guarantee',
      'Advanced analytics',
      'White-label options'
    ],
    apiCalls: -1, // Unlimited
    stripePriceId: 'price_enterprise_monthly',
  },
]

export function SubscriptionManager() {
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const queryClient = useQueryClient()

  // Fetch current subscription
  const { data: subscription, isLoading: subscriptionLoading } = useQuery({
    queryKey: ['subscription'],
    queryFn: async () => {
      const { data: { user } } = await supabase.auth.getUser()
      if (!user) throw new Error('Not authenticated')

      const { data, error } = await supabase
        .from('user_subscriptions')
        .select('*')
        .eq('user_id', user.id)
        .single()

      if (error && error.code !== 'PGRST116') throw error
      return data as UserSubscription | null
    },
  })

  // Subscription mutation
  const subscribeMutation = useMutation({
    mutationFn: async (tierTier: SubscriptionTier) => {
      if (tier.price === 0) return // Free tier doesn't need Stripe

      const { data: { user } } = await supabase.auth.getUser()
      if (!user) throw new Error('Not authenticated')

      // Create Stripe checkout session
      const response = await fetch('/api/stripe/create-checkout', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          priceId: tier.stripePriceId,
          userId: user.id,
        }),
      })

      if (!response.ok) {
        throw new Error('Failed to create checkout session')
      }

      const { url } = await response.json()
      window.location.href = url
    },
    onError: (error) => {
      setError(error.message)
    },
  })

  // Cancel subscription mutation
  const cancelMutation = useMutation({
    mutationFn: async () => {
      const response = await fetch('/api/stripe/cancel-subscription', {
        method: 'POST',
      })

      if (!response.ok) {
        throw new Error('Failed to cancel subscription')
      }

      return response.json()
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['subscription'] })
    },
    onError: (error) => {
      setError(error.message)
    },
  })

  const handleSubscribe = (tier: SubscriptionTier) => {
    setError(null)
    subscribeMutation.mutate(tier)
  }

  const handleCancelSubscription = () => {
    if (confirm('Are you sure you want to cancel your subscription?')) {
      cancelMutation.mutate()
    }
  }

  const getCurrentTier = () => {
    if (!subscription) return subscriptionTiers[0] // Free tier
    return subscriptionTiers.find(t => t.id === subscription.tier) || subscriptionTiers[0]
  }

  const getUsagePercentage = () => {
    if (!subscription) return 0
    if (subscription.apiCallsLimit === -1) return 0 // Unlimited
    return (subscription.apiCallsUsed / subscription.apiCallsLimit) * 100
  }

  if (subscriptionLoading) {
    return (
