        <Card className="border-red-200 bg-red-50">
          <CardContent className="p-4">
            <p className="text-red-600 text-sm">{error}</p>
          </CardContent>
        </Card>
      )}

      {/* Current Subscription */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            Current Plan: {currentTier.name}
            {currentTier.popular && (
              <Badge variant="default">Popular</Badge>
            )}
          </CardTitle>
          <CardDescription>
            {subscription?.status === 'active' 
              ? `Active until ${subscription.currentPeriodEnd.toLocaleDateString()}`
              : 'Free plan with limited features'
            }
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {subscription && subscription.apiCallsLimit !== -1 && (
            <div>
              <div className="flex justify-between text-sm mb-2">
                <span>API Calls Used</span>
                <span>
                  {subscription.apiCallsUsed.toLocaleString()} / {subscription.apiCallsLimit.toLocaleString()}
                </span>
              </div>
              <Progress value={getUsagePercentage()} />
            </div>
          )}

          <div className="flex flex-wrap gap-2">
            {currentTier.features.map((feature, index) => (
              <Badge key={index} variant="outline" className="text-xs">
                ✓ {feature}
              </Badge>
            ))}
          </div>

          {subscription?.status === 'active' && subscription.tier !== 'free' && (
            <div className="flex gap-2">
              <Button 
                variant="outline" 
                size="sm"
                onClick={() => window.open('https://billing.stripe.com/p/login/test_something', '_blank')}
              >
                Manage Billing
              </Button>
              <Button 
                variant="destructive" 
                size="sm"
                onClick={handleCancelSubscription}
                disabled={cancelMutation.isPending}
              >
                {cancelMutation.isPending ? 'Cancelling...' : 'Cancel Subscription'}
              </Button>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Subscription Tiers */}
      <div>
        <h2 className="text-xl font-semibold mb-4">Available Plans</h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {subscriptionTiers.map((tier) => (
            <Card 
              key={tier.id} 
              className={cn(
                "relative",
                tier.popular && "border-primary shadow-lg",
                currentTier.id === tier.id && "ring-2 ring-primary"
              )}
            >
              {tier.popular && (
                <div className="absolute -top-3 left-1/2 transform -translate-x-1/2">
                  <Badge variant="default" className="px-3 py-1">
                    Most Popular
                  </Badge>
                </div>
              )}

              <CardHeader className="text-center pb-2">
                <CardTitle className="text-lg">{tier.name}</CardTitle>
                <div className="text-3xl font-bold">
                  ${tier.price}
                  <span className="text-sm text-muted-foreground font-normal">
                    /{tier.interval}
                  </span>
                </div>
              </CardHeader>

              <CardContent className="space-y-4">
                <ul className="space-y-2">
                  {tier.features.map((feature, index) => (
                    <li key={index} className="flex items-start gap-2 text-sm">
                      <svg className="h-4 w-4 text-green-500 mt-0.5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
                        <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                      </svg>
                      {feature}
                    </li>
                  ))}
                </ul>

                <Button
                  className="w-full"
                  variant={currentTier.id === tier.id ? "outline" : "default"}
                  onClick={() => handleSubscribe(tier)}
                  disabled={
