      <Card>
        <CardHeader>
          <CardTitle>Usage Statistics</CardTitle>
          <CardDescription>
            Your API usage and performance metrics
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="text-center">
              <div className="text-2xl font-bold">{subscription?.apiCallsUsed || 0}</div>
              <div className="text-sm text-muted-foreground">API Calls This Month</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold">
                {subscription?.apiCallsLimit === -1 ? '∞' : subscription?.apiCallsLimit || 1000}
